#!/bin/bash
D="/Users/pragadees.xd/Downloads/Ducky Land/concepts/themes/neon-gen"
CODEX=$(find /Applications/ChatGPT.app/Contents/Resources -maxdepth 4 -name codex -type f -perm -u+x 2>/dev/null | head -1)
id="$1"; desc="$2"
P="home-props-ref.png shows the EXACT art style of our game Ducky Land: flat vector cartoon game props, clean flat colour fills, ONE darker shade band on the lower-right side and ONE soft cream highlight on the upper-left, uniform dark navy ink outlines (#2B2F4F) about 3px thick, no gradients, no texture, no noise, no drop shadow, no glow, no blur. concept.png is the approved concept for our NEON CITY island Tickytown at dusk. Palette: lavender wall #9A9CC0, dusk blue #747699, navy roof #405B87, deep navy #303B61, cream #FFF0C7, and warm sign colours amber #FFB937, coral #F16E4B, pink #F29BB7, mint #6FD8C4, lemon #FFE27A. Neon signs and lit windows are drawn as FLAT solid warm-coloured shapes with a thin cream highlight line, never glowing. Draw, in the home-props-ref style (NOT the painterly concept style), in the same high 3/4 top-down oblique game camera: $desc Isolated on a PLAIN PURE WHITE background, no ground, no grass, no shadow on the ground, no text, no letters, no numbers, no labels, no Duckies, nothing touching the image edges, generous white margin between separate pieces."
"$CODEX" exec -C "$D" -s workspace-write --skip-git-repo-check -c model_reasoning_effort=high -i "$D/home-props-ref.png" -i "$D/concept.png" -- "Use the imagegen skill, built-in image_gen tool, with home-props-ref.png as the style reference and concept.png as the subject reference. Generate ONE image. $P Save it in the current working directory as $id.png. Reply with only the absolute path." < /dev/null > "$D/log-$id.txt" 2>&1
[ -f "$D/$id.png" ] || echo "missing $id" >> "$D/missing.txt"
